import{_ as e,o as i,c as a,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Innovation, Limitations & Ethics","description":"","frontmatter":{},"headers":[],"relativePath":"analysis/innovation-ethics.md","filePath":"analysis/innovation-ethics.md"}'),o={name:"analysis/innovation-ethics.md"};function s(r,t,l,c,h,d){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="innovation-limitations-ethics" tabindex="-1">Innovation, Limitations &amp; Ethics <a class="header-anchor" href="#innovation-limitations-ethics" aria-label="Permalink to &quot;Innovation, Limitations &amp; Ethics&quot;">​</a></h1><h3 id="_23-1-innovation" tabindex="-1">23.1 Innovation <a class="header-anchor" href="#_23-1-innovation" aria-label="Permalink to &quot;23.1 Innovation&quot;">​</a></h3><ol><li><strong>Walletless on both sides.</strong> Not &quot;abstracted for the business&quot;, genuinely absent for sender and recipient.</li><li><strong>Verifiable compliance evidence</strong> across independently licensed parties, the gap left by every player in <a href="./../business/market-analysis.html">this section</a>.</li><li><strong>A legal architecture as a design constraint</strong>, not an afterthought: the orchestrator model is what makes the system buildable without two licences.</li><li><strong>Separating the decision from the proof</strong>, the licensed party decides; the unlicensed party makes it provable.</li></ol><h3 id="_23-2-limitations-first-not-last" tabindex="-1">23.2 Limitations, first, not last <a class="header-anchor" href="#_23-2-limitations-first-not-last" aria-label="Permalink to &quot;23.2 Limitations, first, not last&quot;">​</a></h3><ul><li><strong>We own no licence, no corridor and no liquidity.</strong> Every part of the actual service is someone else&#39;s.</li><li><strong>We do not remove capital lock-up.</strong> We relocate it (<a href="./../business/business-model.html">this section</a>).</li><li><strong>We do not open closed corridors.</strong> Coverage is licensing (<a href="./../legal/why-this-is-legal.html">this section</a>).</li><li><strong>We are trivially copyable</strong> by a licensed CASP that adds an anchor.</li><li><strong>Sandbox, not production.</strong> Real corridors need real licences, real partners, real liquidity.</li><li><strong>Hedera has thin stablecoin liquidity.</strong> A production version would face this immediately.</li><li><strong>Team of one in practice.</strong></li></ul><h3 id="_23-3-ethics" tabindex="-1">23.3 Ethics <a class="header-anchor" href="#_23-3-ethics" aria-label="Permalink to &quot;23.3 Ethics&quot;">​</a></h3><p>The system <strong>cannot make anyone compliant</strong>. It records that a licensed party asserted a check was performed, and when. It does not verify that the check was <em>good</em>, only that it was <em>made</em>, at a time nobody can move, and has not been revised since.</p><p>That distinction is deliberate and must be stated. Presenting the anchor as proof of compliance rather than proof of <em>assertion</em> would be exactly the overclaim this document exists to avoid.</p><hr>',9)])])}const u=e(o,[["render",s]]);export{p as __pageData,u as default};
